using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
        new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 4, Name = "English", Code = "ENGL", Description = "Study of literature, writing, and language." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and civilizations." },
    ];

    private static readonly List<Instructor> Instructors =
    [
        new() { Id = 1, Name = "Dr. Ada Lovelace", Title = "Professor of Computer Science", Bio = "Dr. Lovelace has over 20 years of experience in algorithm design and software engineering. She has published extensively on computational theory and mentors students in advanced programming.", Email = "alovelace@university.edu" },
        new() { Id = 2, Name = "Dr. Alan Turing", Title = "Associate Professor of Computer Science", Bio = "Dr. Turing specializes in artificial intelligence and machine learning. His research focuses on neural networks and their applications in natural language processing.", Email = "aturing@university.edu" },
        new() { Id = 3, Name = "Dr. Emmy Noether", Title = "Professor of Mathematics", Bio = "Dr. Noether is a renowned mathematician specializing in abstract algebra and theoretical physics. She has received numerous awards for her contributions to ring theory.", Email = "enoether@university.edu" },
        new() { Id = 4, Name = "Dr. Richard Feynman", Title = "Professor of Physics", Bio = "Dr. Feynman is a celebrated physicist known for his engaging lectures and research in quantum electrodynamics. He brings complex topics to life through vivid demonstrations.", Email = "rfeynman@university.edu" },
        new() { Id = 5, Name = "Dr. Maya Angelou", Title = "Professor of English", Bio = "Dr. Angelou is an acclaimed author and poet who brings decades of literary experience to the classroom. Her courses emphasize creative expression and critical analysis.", Email = "mangelou@university.edu" },
        new() { Id = 6, Name = "Dr. Howard Zinn", Title = "Associate Professor of History", Bio = "Dr. Zinn is a historian and social activist whose research focuses on labor history and civil rights movements. He encourages students to examine history from multiple perspectives.", Email = "hzinn@university.edu" },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = Instructors[0], IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
        new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques. Includes analysis of time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Location = "Science Hall 305", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = Instructors[0], IsFeatured = false, MaxEnrollment = 60, CurrentEnrollment = 55 },
        new() { Id = 3, Code = "CS 301", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning fundamentals, and neural networks.", Credits = 3, Schedule = "Mon/Wed 2:00–3:30 PM", Location = "Tech Center 110", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = Instructors[1], IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
        new() { Id = 4, Code = "CS 401", Title = "Software Engineering", Description = "Principles of software development including requirements analysis, design patterns, testing strategies, and agile methodologies.", Credits = 3, Schedule = "Tue/Thu 1:00–2:30 PM", Location = "Tech Center 205", DepartmentId = 1, DepartmentName = "Computer Science", Instructor = Instructors[1], IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 32 },
        new() { Id = 5, Code = "MATH 101", Title = "Calculus I", Description = "Limits, continuity, derivatives, and integrals of single-variable functions. Applications to physics and engineering problems.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = Instructors[2], IsFeatured = true, MaxEnrollment = 150, CurrentEnrollment = 130 },
        new() { Id = 6, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and eigenvectors with applications.", Credits = 3, Schedule = "Tue/Thu 9:00–10:30 AM", Location = "Math Building 203", DepartmentId = 2, DepartmentName = "Mathematics", Instructor = Instructors[2], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 65 },
        new() { Id = 7, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Physics Lab 100", DepartmentId = 3, DepartmentName = "Physics", Instructor = Instructors[3], IsFeatured = true, MaxEnrollment = 100, CurrentEnrollment = 87 },
        new() { Id = 8, Code = "PHYS 301", Title = "Quantum Mechanics", Description = "Wave-particle duality, Schrödinger equation, quantum states, and measurement theory. Prerequisites: PHYS 201, MATH 201.", Credits = 3, Schedule = "Tue/Thu 2:00–3:30 PM", Location = "Physics Lab 302", DepartmentId = 3, DepartmentName = "Physics", Instructor = Instructors[3], IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 22 },
        new() { Id = 9, Code = "ENGL 101", Title = "English Composition", Description = "Develop college-level writing skills through essays, research papers, and peer review. Emphasis on clarity, argument, and evidence.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Humanities 110", DepartmentId = 4, DepartmentName = "English", Instructor = Instructors[4], IsFeatured = false, MaxEnrollment = 30, CurrentEnrollment = 28 },
        new() { Id = 10, Code = "ENGL 250", Title = "Creative Writing", Description = "Workshop-based course exploring fiction, poetry, and creative nonfiction. Students produce a portfolio of original work.", Credits = 3, Schedule = "Tue/Thu 3:00–4:30 PM", Location = "Humanities 205", DepartmentId = 4, DepartmentName = "English", Instructor = Instructors[4], IsFeatured = true, MaxEnrollment = 20, CurrentEnrollment = 18 },
        new() { Id = 11, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed 10:00–11:30 AM", Location = "Liberal Arts 300", DepartmentId = 5, DepartmentName = "History", Instructor = Instructors[5], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 60 },
        new() { Id = 12, Code = "HIST 201", Title = "Modern World History", Description = "Exploration of global events from the Renaissance to the present, including colonialism, world wars, and globalization.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:30 PM", Location = "Liberal Arts 305", DepartmentId = 5, DepartmentName = "History", Instructor = Instructors[5], IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 55 },
    ];

    public Task<List<Department>> GetDepartmentsAsync()
    {
        return Task.FromResult(Departments.ToList());
    }

    public Task<List<Course>> GetCoursesAsync(string? searchTerm = null, int? departmentId = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Instructor.Name.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        return Task.FromResult(query.ToList());
    }

    public Task<List<Course>> GetFeaturedCoursesAsync()
    {
        return Task.FromResult(Courses.Where(c => c.IsFeatured).ToList());
    }

    public Task<Course?> GetCourseByIdAsync(int id)
    {
        return Task.FromResult(Courses.FirstOrDefault(c => c.Id == id));
    }

    public Task<bool> SubmitEnrollmentRequestAsync(EnrollmentRequest request)
    {
        // In a real app, this would persist to a database
        var course = Courses.FirstOrDefault(c => c.Id == request.CourseId);
        return Task.FromResult(course is not null && course.CurrentEnrollment < course.MaxEnrollment);
    }
}

