@using UniversityCourseCatalog.Models

<div class="card h-100 shadow-sm">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-start mb-2">
            <span class="badge bg-secondary">@Course.Code</span>
            <span class="badge bg-info text-dark">@Course.Credits credits</span>
        </div>
        <h5 class="card-title">@Course.Title</h5>
        <p class="card-text text-muted small">@Course.DepartmentName</p>
        <p class="card-text">@Truncate(Course.Description, 120)</p>
        <div class="d-flex justify-content-between align-items-center">
            <small class="text-muted">@Course.Instructor.Name</small>
            <a href="@($"courses/{Course.Id}")" class="btn btn-sm btn-outline-primary">View Details</a>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Course Course { get; set; } = default!;

    private static string Truncate(string text, int maxLength)
    {
        return text.Length <= maxLength ? text : string.Concat(text.AsSpan(0, maxLength), "…");
    }
}

@using UniversityCourseCatalog.Models

<div class="mb-4">
    <h3>Departments</h3>
    <div class="list-group">
        @foreach (var dept in Departments)
        {
            <a href="@($"courses?department={dept.Id}")" class="list-group-item list-group-item-action d-flex justify-content-between align-items-center">
                <div>
                    <strong>@dept.Name</strong>
                    <span class="text-muted ms-2">(@dept.Code)</span>
                </div>
                <span class="badge bg-primary rounded-pill">→</span>
            </a>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Department> Departments { get; set; } = [];
}

@using UniversityCourseCatalog.Models

<div class="mb-5">
    <h3 class="mb-3">Featured Courses</h3>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in Courses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Course> Courses { get; set; } = [];
}

@using UniversityCourseCatalog.Models

<div class="row g-3 mb-4">
    <div class="col-md-8">
        <div class="input-group">
            <span class="input-group-text">🔍</span>
            <input type="text"
                   class="form-control"
                   placeholder="Search courses by title, code, description, or instructor…"
                   value="@SearchTerm"
                   @oninput="OnSearchInput" />
            @if (!string.IsNullOrEmpty(SearchTerm))
            {
                <button class="btn btn-outline-secondary" type="button" @onclick="ClearSearch">✕</button>
            }
        </div>
    </div>
    <div class="col-md-4">
        <select class="form-select" value="@SelectedDepartmentId" @onchange="OnDepartmentChanged">
            <option value="0">All Departments</option>
            @foreach (var dept in Departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
</div>

@code {
    [Parameter] public string SearchTerm { get; set; } = string.Empty;
    [Parameter] public int SelectedDepartmentId { get; set; }
    [Parameter] public List<Department> Departments { get; set; } = [];
    [Parameter] public EventCallback<string> SearchTermChanged { get; set; }
    [Parameter] public EventCallback<int> SelectedDepartmentIdChanged { get; set; }

    private async Task OnSearchInput(ChangeEventArgs e)
    {
        SearchTerm = e.Value?.ToString() ?? string.Empty;
        await SearchTermChanged.InvokeAsync(SearchTerm);
    }

    private async Task ClearSearch()
    {
        SearchTerm = string.Empty;
        await SearchTermChanged.InvokeAsync(SearchTerm);
    }

    private async Task OnDepartmentChanged(ChangeEventArgs e)
    {
        SelectedDepartmentId = int.TryParse(e.Value?.ToString(), out var id) ? id : 0;
        await SelectedDepartmentIdChanged.InvokeAsync(SelectedDepartmentId);
    }
}

@using UniversityCourseCatalog.Models

@if (Courses.Count == 0)
{
    <div class="alert alert-info">
        No courses found matching your criteria. Try adjusting your search or filter.
    </div>
}
else
{
    <p class="text-muted mb-3">Showing @Courses.Count course(s)</p>
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var course in Courses)
        {
            <div class="col">
                <CourseCard Course="course" />
            </div>
        }
    </div>
}

