    private int selectedDepartmentId;

    [SupplyParameterFromQuery(Name = "department")]
    public int? InitialDepartmentId { get; set; }

    protected override async Task OnInitializedAsync()
    {
        if (InitialDepartmentId.HasValue)
        {
            selectedDepartmentId = InitialDepartmentId.Value;
        }

        departments = await CatalogService.GetDepartmentsAsync();
        courses = await CatalogService.GetCoursesAsync(searchTerm, selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }

    private async Task OnSearchTermChanged(string term)
    {
        searchTerm = term;
        await LoadCoursesAsync();
    }

    private async Task OnDepartmentChanged(int departmentId)
    {
        selectedDepartmentId = departmentId;
        await LoadCoursesAsync();
    }

    private async Task LoadCoursesAsync()
    {
        courses = await CatalogService.GetCoursesAsync(
            searchTerm,
            selectedDepartmentId > 0 ? selectedDepartmentId : null);
    }
}

