            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active" aria-current="page">@course.Code</li>
        </ol>
    </nav>

    <div class="d-flex justify-content-between align-items-start mb-3">
        <div>
            <h1>@course.Title</h1>
            <span class="badge bg-secondary fs-6 me-2">@course.Code</span>
            <span class="badge bg-info text-dark fs-6">@course.DepartmentName</span>
        </div>
        <a href="@($"enroll?courseId={course.Id}")" class="btn btn-success">Enroll Now</a>
    </div>

    <div class="card mb-4">
