}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject ICatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1 class="mb-4">Enrollment Request</h1>

@if (submitted)
{
    @if (success)
    {
        <div class="alert alert-success">
            <h4 class="alert-heading">Request Submitted!</h4>
            <p>Your enrollment request for <strong>@selectedCourseTitle</strong> has been submitted successfully. You will receive a confirmation via your university email.</p>
            <hr>
            <a href="courses" class="btn btn-outline-success">Browse More Courses</a>
        </div>
    }
    else
    {
        <div class="alert alert-danger">
            <h4 class="alert-heading">Submission Failed</h4>
            <p>We could not process your enrollment request. The course may be full or an error occurred. Please try again or contact the registrar.</p>
            <hr>
            <a href="enroll" class="btn btn-outline-danger">Try Again</a>
        </div>
    }
}
else
{
    <div class="row">
        <div class="col-md-8">
            <div class="card">
                <div class="card-body">
                    <EditForm Model="model" OnValidSubmit="HandleSubmit" FormName="enrollment">
                        <DataAnnotationsValidator />
                        <AntiforgeryToken />

                        <div class="mb-3">
                            <label for="studentName" class="form-label">Full Name</label>
                            <InputText id="studentName" class="form-control" @bind-Value="model.StudentName" />
                            <ValidationMessage For="() => model.StudentName" />
                        </div>

                        <div class="mb-3">
                            <label for="studentId" class="form-label">Student ID</label>
                            <InputText id="studentId" class="form-control" @bind-Value="model.StudentId" placeholder="e.g., CS123456" />
                            <ValidationMessage For="() => model.StudentId" />
                        </div>

                        <div class="mb-3">
                            <label for="courseId" class="form-label">Course</label>
                            <InputSelect id="courseId" class="form-select" @bind-Value="model.CourseId">
                                <option value="0">— Select a course —</option>
                                @if (courses is not null)
                                {
                                    @foreach (var course in courses)
                                    {
                                        <option value="@course.Id">@course.Code — @course.Title (@course.Credits cr)</option>
                                    }
                                }
                            </InputSelect>
                            <ValidationMessage For="() => model.CourseId" />
                        </div>

                        <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                        <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
                    </EditForm>
                </div>
            </div>
        </div>
        <div class="col-md-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h6>Instructions</h6>
                    <ul class="small mb-0">
                        <li>Enter your full legal name as it appears in university records.</li>
                        <li>Your Student ID is 2 letters followed by 6 digits (e.g., CS123456).</li>
                        <li>Select the course you wish to enroll in.</li>
                        <li>You will receive a confirmation email after submission.</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest model { get; set; } = new();

    [SupplyParameterFromQuery(Name = "courseId")]
    public int? PreselectedCourseId { get; set; }

    private List<Course>? courses;
    private bool submitted;
    private bool success;
    private string selectedCourseTitle = string.Empty;

    protected override async Task OnInitializedAsync()
    {
        courses = await CatalogService.GetCoursesAsync();

        if (PreselectedCourseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = PreselectedCourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        selectedCourseTitle = courses?.FirstOrDefault(c => c.Id == model.CourseId)?.Title ?? "Unknown";
        success = await CatalogService.SubmitEnrollmentRequestAsync(model);
        submitted = true;
    }
}

