        courses = await CatalogService.GetCoursesAsync();

        if (PreselectedCourseId.HasValue && model.CourseId == 0)
        {
            model.CourseId = PreselectedCourseId.Value;
        }
    }

    private async Task HandleSubmit()
    {
        selectedCourseTitle = courses?.FirstOrDefault(c => c.Id == model.CourseId)?.Title ?? "Unknown";
        success = await CatalogService.SubmitEnrollmentRequestAsync(model);
        submitted = true;
    }
}

